// Crew pixel scene on the phone: the same side-view building as the desktop
// (desktop/.../components/neovarch/crew-pixel.tsx). Sky, two drifting hill
// layers, brick shell, plank back wall with windows, wooden floors and a desk
// bay per member; members type, walk, wave, cheer, think or slump by status.
// Character frames and palettes come from crew_pixel_data.dart, generated by
// tool/crew_pixel/gen_crew_pixel.py. All art is original.
import 'dart:async';
import 'dart:math' as math;

import 'package:flutter/material.dart';

import '../../ui/widgets/common.dart' show reduceMotion;
import 'crew_pixel_data.dart';

export 'crew_pixel_data.dart';

/// Global switch for widget tests that settle frames (the scene animates forever).
bool crewPixelAnimate = true;

/// What a member does in the scene (mirrors crewPose() on the desktop).
String crewPose(String member, [String? crew]) {
  if (crew == 'proposed') return 'think';
  switch (member) {
    case 'working':
      return 'type';
    case 'reviewing':
      return 'walk';
    case 'waiting':
      return 'wait';
    case 'done':
      return 'cheer';
    case 'error':
      return 'slump';
  }
  return crew == 'running' ? 'walk' : 'idle';
}

/// Frame rows for a pose at [tick] (8 ticks per second).
List<String> crewFrameRows(String pose, int tick) {
  final set = crewFrames[pose] ?? crewFrames['idle']!;
  final i = pose == 'idle' ? (tick % 24 == 23 ? 1 : 0) : (tick ~/ 2) % set.length;
  return set[i];
}

const crewBayW = 40, crewFloorH = 48, _wall = 4, _util = 28, _sky = 16, _roof = 14, _ground = 12;

class CrewLayout {
  CrewLayout(this.scale, this.width, this.cols, this.floors);
  final int scale, width, cols, floors;
  int get height => _sky + _roof + floors * crewFloorH + _ground;
  int bayX(int i) => _wall + (i % cols) * crewBayW;
  int bayY(int i) => _sky + _roof + (i ~/ cols) * crewFloorH;
}

/// Integer-scaled layout for [w] logical px holding [n] members (same math as the desktop).
CrewLayout crewLayout(double w, int n) {
  final scale = w >= 900
      ? 4
      : w >= 330
      ? 3
      : 2;
  final width = math.max(crewBayW + _util + _wall * 2, (w / scale).floor());
  final cols = math.max(1, math.min(6, ((width - _wall * 2 - _util) / crewBayW).floor()));
  return CrewLayout(scale, width, cols, math.max(1, (n / cols).ceil()));
}

class _Pal {
  _Pal(bool dark)
    : sky = dark ? const Color(0xFF141A33) : const Color(0xFF8FD3F4),
      orb = dark ? const Color(0xFFF1ECD2) : const Color(0xFFFFD84A),
      far = dark ? const Color(0xFF26314F) : const Color(0xFF7FB7A0),
      near = dark ? const Color(0xFF1F3A33) : const Color(0xFF4F9A5D),
      plank = dark ? const Color(0xFF5A3D27) : const Color(0xFFA0714A),
      plankLine = dark ? const Color(0xFF432C1B) : const Color(0xFF85593A),
      stars = dark;
  final Color sky, orb, far, near, plank, plankLine;
  final bool stars;
}

int _hill(int x, int amp, int seed) => (amp * (0.6 + 0.4 * math.sin((x + seed) / 9) * math.cos((x + seed * 2) / 23))).round();

void _px(Canvas c, Paint p, num x, num y, num w, num h, int color) {
  p.color = Color(color);
  c.drawRect(Rect.fromLTWH(x.toDouble(), y.toDouble(), w.toDouble(), h.toDouble()), p);
}

void paintCrewFigure(Canvas c, int avatar, String pose, int tick, double x, double y, {bool flip = false}) {
  final pal = crewPalettes[((avatar % 10) + 10) % 10];
  final rows = crewFrameRows(pose, tick);
  final hop = pose == 'cheer' && (tick ~/ 2).isOdd ? -1 : 0;
  final p = Paint()..isAntiAlias = false;
  for (var ry = 0; ry < rows.length; ry++) {
    final row = rows[ry];
    for (var rx = 0; rx < row.length; rx++) {
      final k = row[rx];
      if (k == '.') continue;
      final col = k == 'w'
          ? crewEyeWhite
          : k == 'e'
          ? crewPupil
          : pal[crewKeys.indexOf(k)];
      _px(c, p, x + (flip ? crewW - 1 - rx : rx), y + ry + hop, 1, 1, col);
    }
  }
}

class CrewSceneMember {
  const CrewSceneMember({required this.id, required this.name, required this.avatar, required this.status, this.bubble, this.manager = false});
  final String id, name, status;
  final int avatar;
  final String? bubble;
  final bool manager;
}

class _Placed {
  _Placed(this.m, this.pose, this.x, this.y, this.flip, this.bayX, this.bayY);
  final CrewSceneMember m;
  final String pose;
  final double x, y;
  final bool flip;
  final int bayX, bayY;
}

List<_Placed> _place(CrewLayout l, List<CrewSceneMember> ms, String? crewStatus, int tick) => [
  for (var i = 0; i < ms.length; i++)
    () {
      final pose = crewPose(ms[i].status, crewStatus);
      final bx = l.bayX(i), by = l.bayY(i);
      var x = bx + 9.0;
      var flip = false;
      if (pose == 'walk') {
        const span = 22;
        final p = (tick + i * 7) % (span * 2);
        x = bx + 2.0 + (p < span ? p : span * 2 - p);
        flip = p >= span;
      } else if (pose == 'wait' || pose == 'cheer' || pose == 'slump') {
        x = bx + 6.0;
      }
      return _Placed(ms[i], pose, x, (by + crewFloorH - 4 - crewH).toDouble(), flip, bx, by);
    }(),
];

class CrewScenePainter extends CustomPainter {
  CrewScenePainter({required this.layout, required this.members, required this.crewStatus, required this.tick, required this.dark, required this.accent});
  final CrewLayout layout;
  final List<CrewSceneMember> members;
  final String? crewStatus;
  final int tick;
  final bool dark;
  final Color accent;

  @override
  void paint(Canvas canvas, Size size) {
    final l = layout;
    final pal = _Pal(dark);
    final p = Paint()..isAntiAlias = false;
    canvas.save();
    canvas.scale(l.scale.toDouble());
    final w = l.width, h = l.height, top = _sky + _roof, groundY = h - _ground, utilX = w - _wall - _util;
    _px(canvas, p, 0, 0, w, h, pal.sky.toARGB32());
    if (pal.stars) {
      var i = 0;
      for (final sx in [7, 23, 41, 66, 90, 117, 150, 181, 203]) {
        _px(canvas, p, sx % w, 2 + (i++ * 5) % 12, 1, 1, 0xFFE9E4FF);
      }
    }
    _px(canvas, p, w - 20, 4, 6, 6, pal.orb.toARGB32());
    // hills drift one pixel every few ticks, wrapping every 64 px
    final farOff = (tick ~/ 6) % 64, nearOff = (tick ~/ 3) % 64;
    for (var x = 0; x < w; x++) {
      final fy = top + 18 - _hill(x + farOff, 14, 3);
      _px(canvas, p, x, fy, 1, groundY - fy, pal.far.toARGB32());
      final ny = top + 30 - _hill(x + nearOff, 10, 41);
      _px(canvas, p, x, ny, 1, groundY - ny, pal.near.toARGB32());
    }
    for (var i = 0; i < 4; i++) {
      _px(canvas, p, 12 - i * 4, _sky + i * 3, w - 2 * (12 - i * 4), 3, i.isOdd ? 0xFF6C2219 : 0xFF8F2F24);
    }
    _px(canvas, p, 0, _sky + 12, w, 2, 0xFF6C2219);
    void plank(num x, num y, num pw, num ph) {
      _px(canvas, p, x, y, pw, ph, pal.plank.toARGB32());
      for (var yy = y + 5; yy < y + ph; yy += 6) {
        _px(canvas, p, x, yy, pw, 1, pal.plankLine.toARGB32());
      }
    }

    for (var f = 0; f < l.floors; f++) {
      final y = top + f * crewFloorH, winY = y + 8;
      plank(_wall, y, w - _wall * 2, 8);
      plank(_wall, winY + 10, w - _wall * 2, crewFloorH - 22);
      for (var c = 0; c < l.cols; c++) {
        final bx = _wall + c * crewBayW;
        plank(bx, winY, 24, 10);
        plank(bx + 36, winY, 4, 10);
        _px(canvas, p, bx + 24, winY, 1, 10, 0xFF3A2616);
        _px(canvas, p, bx + 35, winY, 1, 10, 0xFF3A2616);
        _px(canvas, p, bx + 24, winY + 9, 12, 1, 0xFF3A2616);
        // desk + monitor
        final fy = y + crewFloorH;
        _px(canvas, p, bx + 20, fy - 16, 16, 2, 0xFFB07A52);
        _px(canvas, p, bx + 21, fy - 14, 2, 10, 0xFF7A5236);
        _px(canvas, p, bx + 33, fy - 14, 2, 10, 0xFF7A5236);
        _px(canvas, p, bx + 25, fy - 24, 9, 7, 0xFF2B2B33);
        _px(canvas, p, bx + 28, fy - 17, 3, 1, 0xFF9AA0A6);
      }
      plank(utilX, winY, _util, 10);
      _px(canvas, p, _wall, y + crewFloorH - 4, w - _wall * 2, 4, 0xFF9A6A3F);
      _px(canvas, p, _wall, y + crewFloorH - 1, w - _wall * 2, 1, 0xFF6E4A2A);
      final fy = y + crewFloorH;
      if (f == l.floors - 1) {
        _px(canvas, p, utilX + 2, fy - 24, 9, 20, 0xFF2A2D36);
        for (var r = 0; r < 4; r++) {
          final on = (r + tick ~/ 3) % 3 == 0 && tick % 8 < 4;
          _px(canvas, p, utilX + 4, fy - 22 + r * 4, 2, 1, on ? 0xFF5BE37A : 0xFF3E4A3E);
        }
        _px(canvas, p, utilX + 14, fy - 14, 6, 10, 0xFF9AA0A6);
        _px(canvas, p, utilX + 16, fy - 9, 2, 2, 0xFF4B2A17);
        for (var k = 0; k < 3; k++) {
          _px(canvas, p, utilX + 17 + (tick + k) % 2, fy - 17 - k * 2 - tick % 3, 1, 1, 0xB3E8E4DC);
        }
      } else {
        _px(canvas, p, utilX + 2, fy - 26, 10, 22, 0xFF4A311D);
        for (var r = 0; r < 3; r++) {
          _px(canvas, p, utilX + 3, fy - 25 + r * 7, 2, 5, 0xFFC0392B);
          _px(canvas, p, utilX + 6, fy - 25 + r * 7, 2, 5, 0xFF2E86C1);
          _px(canvas, p, utilX + 9, fy - 24 + r * 7, 2, 4, 0xFFD4AC0D);
        }
        _px(canvas, p, utilX + 15, fy - 8, 5, 4, 0xFFA0522D);
        _px(canvas, p, utilX + 14, fy - 13, 7, 5, 0xFF3F8F3A);
      }
      if (f > 0) {
        _px(canvas, p, utilX + 22, y - 4, 1, crewFloorH, 0xFF8A5A3B);
        _px(canvas, p, utilX + 26, y - 4, 1, crewFloorH, 0xFF8A5A3B);
        for (var r = 0; r < 13; r++) {
          _px(canvas, p, utilX + 22, y - 4 + r * 4, 5, 1, 0xFF8A5A3B);
        }
      }
    }
    // stone shell
    for (final wx in [0, w - _wall]) {
      _px(canvas, p, wx, top - 2, _wall, groundY - top + 2, 0xFF6B6A72);
      for (var yy = top + 1; yy < groundY; yy += 4) {
        _px(canvas, p, wx, yy, _wall, 1, 0xFF4A4950);
      }
    }
    _px(canvas, p, 0, groundY, w, _ground, 0xFF6A4A2F);
    _px(canvas, p, 0, groundY, w, 2, 0xFF3F8F3A);
    for (var i = 0; i * 7 < w; i++) {
      _px(canvas, p, i * 7 + i % 3, groundY + 4 + (i % 4) * 2, 2, 1, 0xFF54391F);
    }
    for (final pl in _place(l, members, crewStatus, tick)) {
      if (pl.pose == 'type') {
        _px(canvas, p, pl.bayX + 9, pl.y + 11, 3, 8, 0xFF3B3B44);
        _px(canvas, p, pl.bayX + 26, pl.bayY + crewFloorH - 23, 7, 5, accent.toARGB32());
      }
      paintCrewFigure(canvas, pl.m.avatar, pl.pose, tick, pl.x, pl.y, flip: pl.flip);
      if (pl.pose == 'walk' && pl.m.status == 'reviewing') {
        _px(canvas, p, pl.flip ? pl.x - 1 : pl.x + 10, pl.y + 10, 3, 4, 0xFFB67F12);
      }
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(CrewScenePainter old) =>
      old.tick != tick || old.members != members || old.layout.width != layout.width || old.dark != dark || old.crewStatus != crewStatus;
}

/// 8 fps ticker shared by the scene and solo stations; static under reduce motion.
mixin _CrewTicker<T extends StatefulWidget> on State<T> {
  int tick = 0;
  Timer? _timer;
  bool get wantsTick => true;

  void syncTicker() {
    _timer?.cancel();
    _timer = null;
    if (!crewPixelAnimate || !wantsTick) return;
    _timer = Timer.periodic(const Duration(milliseconds: 125), (_) {
      if (mounted && !reduceMotion(context)) setState(() => tick++);
    });
  }

  @override
  void initState() {
    super.initState();
    syncTicker();
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }
}

/// The whole building with name tags and speech bubbles over it.
class CrewScene extends StatefulWidget {
  const CrewScene({super.key, required this.members, this.crewStatus, this.accent = const Color(0xFFEE1C1C), this.label});
  final List<CrewSceneMember> members;
  final String? crewStatus;
  final Color accent;
  final String? label;
  @override
  State<CrewScene> createState() => _CrewSceneState();
}

class _CrewSceneState extends State<CrewScene> with _CrewTicker {
  @override
  Widget build(BuildContext context) {
    final dark = Theme.of(context).brightness == Brightness.dark;
    return LayoutBuilder(
      builder: (context, c) {
        final l = crewLayout(c.maxWidth.isFinite ? c.maxWidth : 360, widget.members.length);
        final s = l.scale.toDouble();
        final placed = _place(l, widget.members, widget.crewStatus, tick);
        return Semantics(
          label: widget.label,
          image: true,
          child: SizedBox(
            width: l.width * s,
            height: l.height * s,
            child: Stack(
              clipBehavior: Clip.hardEdge,
              children: [
                Positioned.fill(
                  child: CustomPaint(
                    painter: CrewScenePainter(layout: l, members: widget.members, crewStatus: widget.crewStatus, tick: tick, dark: dark, accent: widget.accent),
                  ),
                ),
                for (final pl in placed)
                  Positioned(
                    key: ValueKey('crew-fig-${pl.m.id}'),
                    left: pl.x * s,
                    top: pl.y * s,
                    width: crewW * s,
                    height: crewH * s,
                    child: SizedBox(key: ValueKey('crew-station-${pl.m.status}')),
                  ),
                for (final pl in placed)
                  Positioned(
                    key: ValueKey('crew-tag-${pl.m.id}'),
                    left: (pl.x + crewW / 2) * s - 60,
                    width: 120,
                    bottom: (l.height - pl.y + 2) * s,
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        if (pl.m.bubble != null && pl.m.bubble!.isNotEmpty) _Bubble(pl.m.bubble!, pl.m.status, think: pl.pose == 'think'),
                        const SizedBox(height: 2),
                        Container(
                          padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 1),
                          decoration: BoxDecoration(color: const Color(0xB80A0A0E), borderRadius: BorderRadius.circular(3)),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              if (pl.m.manager) Container(width: 6, height: 6, margin: const EdgeInsets.only(right: 3), color: const Color(0xFFF2B134)),
                              Flexible(
                                child: Text(
                                  pl.m.name,
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: const TextStyle(color: Color(0xFFF4F2ED), fontSize: 10, fontWeight: FontWeight.w600),
                                ),
                              ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  ),
              ],
            ),
          ),
        );
      },
    );
  }
}

class _Bubble extends StatelessWidget {
  const _Bubble(this.text, this.status, {this.think = false});
  final String text, status;
  final bool think;
  @override
  Widget build(BuildContext context) {
    final bg = status == 'waiting'
        ? const Color(0xFFF2B134)
        : status == 'error'
        ? const Color(0xFFEE1C1C)
        : status == 'done'
        ? const Color(0xFF2F9E74)
        : const Color(0xFFF4F2ED);
    final fg = status == 'error' || status == 'done' ? Colors.white : const Color(0xFF1A1010);
    return Container(
      key: ValueKey('crew-bubble-$status'),
      constraints: const BoxConstraints(maxWidth: 116),
      padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
      decoration: BoxDecoration(
        color: bg,
        border: Border.all(color: const Color(0xFF1A1010), width: 2),
      ),
      child: Text(
        text,
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
        style: TextStyle(color: fg, fontSize: 10, fontStyle: think ? FontStyle.italic : FontStyle.normal),
      ),
    );
  }
}

/// One member alone in a small bay (onboarding), [width] logical px wide (32×28 cells).
class CrewStation extends StatefulWidget {
  const CrewStation({super.key, required this.avatar, required this.status, this.width = 110, required this.chair, required this.accent, this.animate = true});
  final int avatar;
  final String status;
  final double width;
  final Color chair;
  final Color accent;
  final bool animate;
  @override
  State<CrewStation> createState() => _CrewStationState();
}

class _CrewStationState extends State<CrewStation> with _CrewTicker {
  @override
  bool get wantsTick => widget.animate;

  @override
  Widget build(BuildContext context) => SizedBox(
    width: widget.width,
    height: widget.width * 28 / 32,
    child: CustomPaint(
      key: ValueKey('crew-station-${widget.status}'),
      painter: _SoloPainter(widget.avatar, crewPose(widget.status), tick, widget.accent, widget.status),
    ),
  );
}

class _SoloPainter extends CustomPainter {
  _SoloPainter(this.avatar, this.pose, this.tick, this.accent, this.status);
  final int avatar, tick;
  final String pose, status;
  final Color accent;
  @override
  void paint(Canvas canvas, Size size) {
    final p = Paint()..isAntiAlias = false;
    canvas.save();
    canvas.scale(size.width / 32);
    _px(canvas, p, 0, 0, 32, 24, 0xFF5A3D27);
    _px(canvas, p, 0, 24, 32, 4, 0xFF9A6A3F);
    _px(canvas, p, 18, 14, 12, 2, 0xFFB07A52);
    _px(canvas, p, 19, 16, 2, 8, 0xFF7A5236);
    _px(canvas, p, 21, 7, 8, 6, 0xFF2B2B33);
    if (pose == 'type') _px(canvas, p, 22, 8, 6, 4, accent.toARGB32());
    paintCrewFigure(canvas, avatar, pose, tick, pose == 'type' ? 6 : 3, 3);
    if (status == 'done' || status == 'waiting' || status == 'error') {
      _px(
        canvas,
        p,
        13,
        0,
        5,
        4,
        status == 'done'
            ? 0xFF2F9E74
            : status == 'waiting'
            ? 0xFFF2B134
            : 0xFFEE1C1C,
      );
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(_SoloPainter old) => old.tick != tick || old.pose != pose || old.avatar != avatar;
}
